CREATE TABLE IF NOT EXISTS project_intents (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_prompt TEXT NOT NULL, target_audience TEXT NOT NULL DEFAULT '', platforms JSONB NOT NULL DEFAULT '[]', constraints_json JSONB NOT NULL DEFAULT '[]', preferences JSONB NOT NULL DEFAULT '[]', budget JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_requirements (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, category TEXT NOT NULL, description TEXT NOT NULL, priority TEXT NOT NULL, required BOOLEAN NOT NULL DEFAULT false, source TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS technology_stacks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, language TEXT NOT NULL, framework TEXT NOT NULL, runtime TEXT NOT NULL, package_manager TEXT NOT NULL, build_system TEXT NOT NULL, test_framework JSONB NOT NULL DEFAULT '[]', e2e_framework JSONB NOT NULL DEFAULT '[]', database_name TEXT NOT NULL DEFAULT '', infrastructure JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS architecture_decisions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, status TEXT NOT NULL, selected_id TEXT NOT NULL, selected_stack_id TEXT REFERENCES technology_stacks(id), override_value TEXT NOT NULL DEFAULT '', reasons JSONB NOT NULL DEFAULT '[]', rejected JSONB NOT NULL DEFAULT '{}', raw_evidence JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS environment_manifests (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version TEXT NOT NULL, base_image TEXT NOT NULL, os_name TEXT NOT NULL, architecture TEXT NOT NULL, profile TEXT NOT NULL, decision_id TEXT REFERENCES architecture_decisions(id), manifest JSONB NOT NULL, fingerprint TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(project_id, version));
CREATE TABLE IF NOT EXISTS environment_versions (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, manifest_id TEXT NOT NULL REFERENCES environment_manifests(id), version TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(project_id,version));
CREATE TABLE IF NOT EXISTS provisioning_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT, manifest_id TEXT REFERENCES environment_manifests(id), status TEXT NOT NULL, last_successful_step TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, cancel_requested BOOLEAN NOT NULL DEFAULT false, run JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS provisioning_steps (run_id TEXT NOT NULL REFERENCES provisioning_runs(id) ON DELETE CASCADE, step_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, dependencies JSONB NOT NULL DEFAULT '[]', required BOOLEAN NOT NULL, progress INTEGER NOT NULL DEFAULT 0, evidence TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, PRIMARY KEY(run_id,step_id));
CREATE TABLE IF NOT EXISTS environment_installations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL, fingerprint TEXT NOT NULL DEFAULT '', installed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS agent_installations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, agent_id TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL, fingerprint TEXT NOT NULL DEFAULT '', installed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS browser_installations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, engine TEXT NOT NULL, automation TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL, installed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS environment_verifications (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, status TEXT NOT NULL, fingerprint JSONB NOT NULL, checks JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS environment_events (id BIGSERIAL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, run_id TEXT REFERENCES provisioning_runs(id) ON DELETE CASCADE, type TEXT NOT NULL, step_id TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, message TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0, payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
